import jwt
import os
from datetime import datetime, timedelta, timezone

SECRET = os.environ['JWT_SECRET']


def make_token(user):
    payload = {'user': user, 'exp': datetime.now(timezone.utc) + timedelta(minutes=15)}
    return jwt.encode(payload, SECRET, algorithm='RS256')
